//! Runtime reflection and a self-describing binary format (RTTIBin).
//!
//! Three layers:
//!
//! 1. **`Reflect`**: type self-description (field names, offsets, field
//!    types), generated by `#[derive(Reflect)]`. `TypeDesc` is built lazily
//!    on first access.
//! 2. **`TypeRegistry`**: `TypeId -> TypeDesc` plus a constructor, so an
//!    `Object` can be restored to a `Box<dyn Any>` without knowing the
//!    concrete Rust type.
//! 3. **`rtti_bin`**: encodes an `Object` tree into a binary "type table +
//!    object table", the equivalent of Decima's `RTTIBin`: the data carries
//!    its own schema, so the reader needs no compile-time type.
//!
//! ## Relationship to `serde`
//!
//! `serde` serializes types known at compile time; this crate handles cases
//! where the type is only known at runtime (editor, cooking, cross-version
//! assets). The two coexist: authoring formats still use JSON, while cooked
//! formats use RTTIBin.
//!
//! ## Cargo features
//!
//! - `derive` (default): re-exports `#[derive(Reflect)]`; without it you can
//!   still hand-write `impl Reflect`.
//! - `glam` (default): implements `Reflect` for glam vector / quaternion
//!   types; without it those impls are simply absent.
//!
//! Both features can be disabled independently, for example
//! `cargo check -p prism-reflect --no-default-features` (CI runs this).

mod desc;
#[cfg(feature = "glam")]
mod glam_impls;
mod registry;
pub mod rtti_bin;

pub use desc::{FieldDesc, FieldType, TypeDesc, TypeId, TypeKind};
pub use registry::{TypeEntry, TypeRegistry};

#[cfg(feature = "derive")]
pub use prism_reflect_derive::Reflect;

use std::collections::BTreeMap;
use std::fmt;

/// Error from reflective reads/writes or decoding.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReflectError {
    /// The field is not present in the type description.
    UnknownField(String),
    /// The field is marked read-only.
    ReadOnly(String),
    /// The runtime type of a `Value` does not match the field declaration.
    TypeMismatch {
        expected: &'static str,
        got: &'static str,
    },
    /// The `Object` type id does not match the target type.
    TypeIdMismatch { expected: TypeId, got: TypeId },
    /// The type is not registered in the `TypeRegistry`.
    NotRegistered(TypeId),
    /// Corrupt data, out-of-bounds access, or nesting depth exceeded.
    BadData(String),
}

impl fmt::Display for ReflectError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::UnknownField(name) => write!(f, "unknown field '{name}'"),
            Self::ReadOnly(name) => write!(f, "field '{name}' is read-only"),
            Self::TypeMismatch { expected, got } => {
                write!(f, "type mismatch: expected {expected}, got {got}")
            }
            Self::TypeIdMismatch { expected, got } => {
                write!(
                    f,
                    "type id mismatch: expected {:?}, got {:?}",
                    expected, got
                )
            }
            Self::NotRegistered(id) => write!(f, "type {:?} is not registered", id),
            Self::BadData(msg) => write!(f, "bad reflected data: {msg}"),
        }
    }
}

impl std::error::Error for ReflectError {}

/// A dynamic value in the reflection layer.
///
/// Integers are uniformly narrowed to `I64` / `U64` and floats to `F64`;
/// the field's real type is decided by `TypeDesc`, and range checks happen
/// in `from_value`.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    None,
    Bool(bool),
    I64(i64),
    U64(u64),
    F64(f64),
    Str(String),
    List(Vec<Value>),
    Object(Object),
}

impl Value {
    /// Stable type tag, used in error messages and binary tags.
    pub fn kind(&self) -> &'static str {
        match self {
            Self::None => "none",
            Self::Bool(_) => "bool",
            Self::I64(_) => "i64",
            Self::U64(_) => "u64",
            Self::F64(_) => "f64",
            Self::Str(_) => "string",
            Self::List(_) => "list",
            Self::Object(_) => "object",
        }
    }

    pub fn is_none(&self) -> bool {
        matches!(self, Self::None)
    }

    pub fn as_bool(&self) -> Result<bool, ReflectError> {
        match self {
            Self::Bool(v) => Ok(*v),
            other => Err(ReflectError::TypeMismatch {
                expected: "bool",
                got: other.kind(),
            }),
        }
    }

    pub fn as_i64(&self) -> Result<i64, ReflectError> {
        match self {
            Self::I64(v) => Ok(*v),
            Self::U64(v) => i64::try_from(*v).map_err(|_| ReflectError::TypeMismatch {
                expected: "i64 (in range)",
                got: "u64 (out of range)",
            }),
            other => Err(ReflectError::TypeMismatch {
                expected: "i64",
                got: other.kind(),
            }),
        }
    }

    pub fn as_u64(&self) -> Result<u64, ReflectError> {
        match self {
            Self::U64(v) => Ok(*v),
            Self::I64(v) => u64::try_from(*v).map_err(|_| ReflectError::TypeMismatch {
                expected: "u64 (in range)",
                got: "i64 (out of range)",
            }),
            other => Err(ReflectError::TypeMismatch {
                expected: "u64",
                got: other.kind(),
            }),
        }
    }

    pub fn as_f64(&self) -> Result<f64, ReflectError> {
        match self {
            Self::F64(v) => Ok(*v),
            other => Err(ReflectError::TypeMismatch {
                expected: "f64",
                got: other.kind(),
            }),
        }
    }

    pub fn as_f32(&self) -> Result<f32, ReflectError> {
        Ok(self.as_f64()? as f32)
    }

    pub fn as_str(&self) -> Result<&str, ReflectError> {
        match self {
            Self::Str(v) => Ok(v),
            other => Err(ReflectError::TypeMismatch {
                expected: "string",
                got: other.kind(),
            }),
        }
    }

    pub fn as_list(&self) -> Result<&[Value], ReflectError> {
        match self {
            Self::List(v) => Ok(v),
            other => Err(ReflectError::TypeMismatch {
                expected: "list",
                got: other.kind(),
            }),
        }
    }

    pub fn as_object(&self) -> Result<&Object, ReflectError> {
        match self {
            Self::Object(v) => Ok(v),
            other => Err(ReflectError::TypeMismatch {
                expected: "object",
                got: other.kind(),
            }),
        }
    }
}

/// A reflected object indexed by field name.
///
/// `BTreeMap` makes the encoding order deterministic, so encoding the same
/// object twice yields identical bytes.
#[derive(Debug, Clone, PartialEq)]
pub struct Object {
    pub type_id: TypeId,
    pub type_name: String,
    pub fields: BTreeMap<String, Value>,
}

impl Object {
    pub fn new(type_id: TypeId, type_name: impl Into<String>) -> Self {
        Self {
            type_id,
            type_name: type_name.into(),
            fields: BTreeMap::new(),
        }
    }

    pub fn get(&self, field: &str) -> Option<&Value> {
        self.fields.get(field)
    }

    pub fn insert(&mut self, field: impl Into<String>, value: Value) -> Option<Value> {
        self.fields.insert(field.into(), value)
    }

    pub fn is_empty(&self) -> bool {
        self.fields.is_empty()
    }
}

/// A type that can be reflected.
///
/// Contracts:
/// - It must implement `Default`: `from_object` starts from defaults and
///   keeps missing fields at their default, which makes schema evolution
///   easier.
/// - Its field layout is described by the `TypeDesc` generated by
///   `#[derive(Reflect)]`.
pub trait Reflect: 'static + Default + Sized {
    /// Static description of the type (field names, offsets, types, version).
    fn type_desc() -> &'static TypeDesc;

    /// Reads a field by name.
    fn get_field(&self, field: &str) -> Option<Value>;

    /// Writes a field by name. Read-only fields return
    /// [`ReflectError::ReadOnly`].
    fn set_field(&mut self, field: &str, value: Value) -> Result<(), ReflectError>;

    /// Write path that ignores `read_only`, used by deserialization.
    ///
    /// Defaults to [`Self::set_field`]; the derive macro overrides it so
    /// `from_object` can restore runtime-generated or read-only fields (for
    /// example asset ids).
    fn set_field_force(&mut self, field: &str, value: Value) -> Result<(), ReflectError> {
        self.set_field(field, value)
    }

    /// Converts to a dynamic object (fields ordered by `BTreeMap`).
    fn to_object(&self) -> Object {
        let desc = Self::type_desc();
        let mut object = Object::new(desc.id, desc.name);
        for field in &desc.fields {
            if let Some(value) = self.get_field(field.name) {
                object.fields.insert(field.name.to_owned(), value);
            }
        }
        object
    }

    /// Restores from a dynamic object. Missing fields keep their `Default`
    /// and unknown fields are ignored (for cross-version compatibility;
    /// callers that need strict validation must compare the schema
    /// themselves).
    fn from_object(object: &Object) -> Result<Self, ReflectError> {
        let desc = Self::type_desc();
        if object.type_id != desc.id {
            return Err(ReflectError::TypeIdMismatch {
                expected: desc.id,
                got: object.type_id,
            });
        }

        let mut this = Self::default();
        for field in &desc.fields {
            if let Some(value) = object.fields.get(field.name) {
                this.set_field_force(field.name, value.clone())?;
            }
        }
        Ok(this)
    }
}

/// Bridge between a field type and a reflected value.
///
/// Generated by `#[derive(Reflect)]` for structs, with built-in impls for
/// primitive types, `String`, `Vec<T>`, and `Option<T>`.
pub trait ReflectType: Sized {
    /// This type's description in the schema.
    fn field_type() -> FieldType;

    /// Variant names of an enum in declaration order; **these must be the
    /// strings used in authored JSON**.
    ///
    /// Returns `None` for non-enum fields. The editor uses this to render the
    /// field as a dropdown (see `FieldSchema::variants` in
    /// `prism-editor-api`). This is **editor-only metadata**: it does not
    /// participate in `TypeDesc::schema_hash`, so renaming a variant does not
    /// invalidate cooked data.
    fn enum_variants() -> Option<&'static [&'static str]> {
        None
    }

    /// Value to reflected value.
    fn to_value(&self) -> Value;

    /// Reflected value to value, with type and range checks.
    fn from_value(value: Value) -> Result<Self, ReflectError>;
}

macro_rules! impl_int_reflect {
    ($ty:ty, $field:ident) => {
        impl ReflectType for $ty {
            fn field_type() -> FieldType {
                FieldType::$field
            }

            fn to_value(&self) -> Value {
                Value::I64(*self as i64)
            }

            fn from_value(value: Value) -> Result<Self, ReflectError> {
                let raw = value.as_i64()?;
                <$ty>::try_from(raw).map_err(|_| ReflectError::TypeMismatch {
                    expected: stringify!($ty),
                    got: "out-of-range integer",
                })
            }
        }
    };
}

macro_rules! impl_uint_reflect {
    ($ty:ty, $field:ident) => {
        impl ReflectType for $ty {
            fn field_type() -> FieldType {
                FieldType::$field
            }

            fn to_value(&self) -> Value {
                Value::U64(*self as u64)
            }

            fn from_value(value: Value) -> Result<Self, ReflectError> {
                let raw = value.as_u64()?;
                <$ty>::try_from(raw).map_err(|_| ReflectError::TypeMismatch {
                    expected: stringify!($ty),
                    got: "out-of-range integer",
                })
            }
        }
    };
}

impl_int_reflect!(i8, I8);
impl_int_reflect!(i16, I16);
impl_int_reflect!(i32, I32);
impl_int_reflect!(i64, I64);
impl_uint_reflect!(u8, U8);
impl_uint_reflect!(u16, U16);
impl_uint_reflect!(u32, U32);
impl_uint_reflect!(u64, U64);

impl ReflectType for bool {
    fn field_type() -> FieldType {
        FieldType::Bool
    }

    fn to_value(&self) -> Value {
        Value::Bool(*self)
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        value.as_bool()
    }
}

impl ReflectType for f32 {
    fn field_type() -> FieldType {
        FieldType::F32
    }

    fn to_value(&self) -> Value {
        Value::F64(*self as f64)
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        value.as_f32()
    }
}

impl ReflectType for f64 {
    fn field_type() -> FieldType {
        FieldType::F64
    }

    fn to_value(&self) -> Value {
        Value::F64(*self)
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        value.as_f64()
    }
}

impl ReflectType for String {
    fn field_type() -> FieldType {
        FieldType::String
    }

    fn to_value(&self) -> Value {
        Value::Str(self.clone())
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        match value {
            Value::Str(v) => Ok(v),
            other => Err(ReflectError::TypeMismatch {
                expected: "string",
                got: other.kind(),
            }),
        }
    }
}

impl<T: ReflectType> ReflectType for Vec<T> {
    fn field_type() -> FieldType {
        FieldType::List(Box::new(T::field_type()))
    }

    /// Containers forward the inner enum's variant names: the editor dropdown
    /// for a `Vec<Enum>` field needs them.
    fn enum_variants() -> Option<&'static [&'static str]> {
        T::enum_variants()
    }

    fn to_value(&self) -> Value {
        Value::List(self.iter().map(T::to_value).collect())
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        match value {
            Value::List(items) => items.into_iter().map(T::from_value).collect(),
            other => Err(ReflectError::TypeMismatch {
                expected: "list",
                got: other.kind(),
            }),
        }
    }
}

impl<T: ReflectType> ReflectType for Option<T> {
    fn field_type() -> FieldType {
        FieldType::Optional(Box::new(T::field_type()))
    }

    /// Same as [`Vec<T>`]: the variant names belong to the inner enum, so
    /// `Option<Enum>` keeps them too.
    fn enum_variants() -> Option<&'static [&'static str]> {
        T::enum_variants()
    }

    fn to_value(&self) -> Value {
        match self {
            Some(value) => value.to_value(),
            None => Value::None,
        }
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        if value.is_none() {
            Ok(None)
        } else {
            T::from_value(value).map(Some)
        }
    }
}

impl<T: ReflectType, const N: usize> ReflectType for [T; N] {
    fn field_type() -> FieldType {
        FieldType::Array(Box::new(T::field_type()), N)
    }

    /// Same as [`Vec<T>`]: enums inside fixed-size arrays must render
    /// dropdowns too.
    fn enum_variants() -> Option<&'static [&'static str]> {
        T::enum_variants()
    }

    fn to_value(&self) -> Value {
        Value::List(self.iter().map(T::to_value).collect())
    }

    fn from_value(value: Value) -> Result<Self, ReflectError> {
        let items = value.as_list()?;
        if items.len() != N {
            return Err(ReflectError::TypeMismatch {
                expected: "array of the declared length",
                got: "list of a different length",
            });
        }
        let values: Vec<T> = items
            .iter()
            .cloned()
            .map(T::from_value)
            .collect::<Result<_, _>>()?;
        values.try_into().map_err(|_| ReflectError::TypeMismatch {
            expected: "array of the declared length",
            got: "list of a different length",
        })
    }
}
